/** @jsxImportSource hono/jsx */
import { cn, type ClassValue } from "@/registry/lib/cn"

// Progress — shadcn-htmx, htmx v4 + Tailwind v4.
//
// Source of truth (track visual):
//   repos/shadcn-ui/apps/v4/registry/new-york-v4/ui/progress.tsx
//
// Upstream uses Radix Progress.Root + Indicator. For SSR we render a real
// progressbar element: role="progressbar" + aria-valuemin/max/now/text.
// Pass value=undefined to render the indeterminate state (per ARIA spec).
//
// Refs:
//   repos/mdn/files/en-us/web/accessibility/aria/reference/roles/progressbar_role/
//   repos/mdn/files/en-us/web/html/reference/elements/progress/  (native; we don't use this — limited styling)

type ProgressProps = {
  // 0–max (or max prop). Pass undefined for indeterminate ("we don't
  // know how long this will take").
  value?: number
  max?: number
  min?: number
  // Accessible name — required when there's no visible label.
  ariaLabel?: string
  ariaLabelledby?: string
  // Optional human-readable label, e.g. "Uploading… 42 of 100 MB".
  ariaValuetext?: string
  class?: ClassValue
  id?: string
  // Forwarded to the root <div role="progressbar">. Progress is the textbook
  // htmx polling target — re-render the bar from the server on a recurring
  // trigger (hx-get + hx-trigger="every 2s", repos/htmx htmx-guidance.md Polling).
  [key: `hx-${string}`]: any
  [key: `data-${string}`]: any
}

export function Progress(props: ProgressProps) {
  const {
    value,
    max = 100,
    min = 0,
    ariaLabel,
    ariaLabelledby,
    ariaValuetext,
    class: className,
    id,
    ...rest
  } = props
  const determinate = value !== undefined
  const pct = determinate ? Math.min(100, Math.max(0, ((value! - min) / (max - min)) * 100)) : 0
  return (
    <div
      id={id}
      role="progressbar"
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuenow={determinate ? value : undefined}
      aria-valuetext={ariaValuetext}
      data-slot="progress"
      data-state={determinate ? "determinate" : "indeterminate"}
      class={cn(
        "relative h-2 w-full overflow-hidden rounded-full bg-primary/20",
        className,
      )}
      {...rest}
    >
      <div
        data-slot="progress-indicator"
        class={cn(
          "h-full bg-primary transition-all",
          // Indeterminate state animates a 30%-width bar across the track.
          !determinate && "absolute inset-y-0 -left-1/3 w-1/3 animate-[scn-progress-indeterminate_1.2s_ease-in-out_infinite]",
        )}
        style={determinate ? `width: ${pct}%` : undefined}
      />
    </div>
  )
}

{# Progress macro — shadcn-htmx, htmx v4 + Tailwind v4.
   Mirrors registry/ui/progress.tsx. Pass value=none for indeterminate. #}

{# **attrs forwards arbitrary attributes (e.g. hx-* polling) onto the
   progressbar root — repos/htmx htmx-guidance.md Polling (hx-get + every 2s). #}
{% macro progress(value=none, min=0, max=100, aria_label=none, aria_labelledby=none, aria_valuetext=none, id=none, extra_class="", **attrs) %}
{%- set determinate = value is not none -%}
{%- set pct = ((value - min) / (max - min) * 100) if determinate else 0 -%}
<div {% if id %}id="{{ id }}"{% endif %}
     role="progressbar"
     {% if aria_label %}aria-label="{{ aria_label }}"{% endif %}
     {% if aria_labelledby %}aria-labelledby="{{ aria_labelledby }}"{% endif %}
     aria-valuemin="{{ min }}" aria-valuemax="{{ max }}"
     {% if determinate %}aria-valuenow="{{ value }}"{% endif %}
     {% if aria_valuetext %}aria-valuetext="{{ aria_valuetext }}"{% endif %}
     data-slot="progress" data-state="{{ 'determinate' if determinate else 'indeterminate' }}"
     class="relative h-2 w-full overflow-hidden rounded-full bg-primary/20 {{ extra_class }}"
     {%- for k, v in attrs.items() %} {{ k|replace('_','-') }}="{{ v }}"{% endfor %}>
  <div data-slot="progress-indicator"
       class="h-full bg-primary transition-all {% if not determinate %}absolute inset-y-0 -left-1/3 w-1/3 animate-[scn-progress-indeterminate_1.2s_ease-in-out_infinite]{% endif %}"
       {% if determinate %}style="width: {{ pct }}%"{% endif %}></div>
</div>
{% endmacro %}

{{/* Progress template — shadcn-htmx, htmx v4 + Tailwind v4.
     Pass Value as nil for indeterminate.
     .Attrs (map[string]string) forwards arbitrary attributes (e.g. hx-*
     polling) onto the progressbar root — repos/htmx htmx-guidance.md Polling. */}}

{{define "progress"}}
{{- $min := or .Min 0 -}}
{{- $max := or .Max 100 -}}
{{- $determinate := false -}}{{- if .Value -}}{{- $determinate = true -}}{{- end -}}
<div {{if .ID}}id="{{.ID}}"{{end}}
     role="progressbar"
     {{if .AriaLabel}}aria-label="{{.AriaLabel}}"{{end}}
     {{if .AriaLabelledby}}aria-labelledby="{{.AriaLabelledby}}"{{end}}
     aria-valuemin="{{$min}}" aria-valuemax="{{$max}}"
     {{if $determinate}}aria-valuenow="{{deref .Value}}"{{end}}
     {{if .AriaValuetext}}aria-valuetext="{{.AriaValuetext}}"{{end}}
     data-slot="progress" data-state="{{if $determinate}}determinate{{else}}indeterminate{{end}}"
     class="relative h-2 w-full overflow-hidden rounded-full bg-primary/20"
     {{- range $k, $v := .Attrs}} {{$k}}="{{$v}}"{{end -}}>
  <div data-slot="progress-indicator"
       class="h-full bg-primary transition-all{{if not $determinate}} absolute inset-y-0 -left-1/3 w-1/3 animate-[scn-progress-indeterminate_1.2s_ease-in-out_infinite]{{end}}"
       {{if $determinate}}style="width: {{deref .Value}}%"{{end}}></div>
</div>
{{end}}

{# progress — Django Cotton. See registry/ui/progress.tsx for platform references. #}
<c-vars
  :value="None"
  :min="0"
  :max="100"
  :aria-label="None"
  :aria-labelledby="None"
  :aria-valuetext="None"
  :id="None"
  class=""
/>
{% load l10n %}{% localize off %}
{% load shadcn_htmx %}
{% scn_progress value min max as progress_data %}
<div {% if id %}id="{{ id|default_if_none:"" }}"{% endif %}
     role="progressbar"
     {% if aria_label %}aria-label="{{ aria_label|default_if_none:"" }}"{% endif %}
     {% if aria_labelledby %}aria-labelledby="{{ aria_labelledby|default_if_none:"" }}"{% endif %}
     aria-valuemin="{{ min }}" aria-valuemax="{{ max }}"
     {% if value is not None %}aria-valuenow="{{ progress_data.value }}"{% endif %}
     {% if aria_valuetext %}aria-valuetext="{{ aria_valuetext|default_if_none:"" }}"{% endif %}
     data-slot="progress" data-state="{% if value is None %}indeterminate{% else %}determinate{% endif %}"
     class="relative h-2 w-full overflow-hidden rounded-full bg-primary/20 {{ class }}" {{ attrs }}>
  <div data-slot="progress-indicator"
       class="h-full bg-primary transition-all {% if value is None %}absolute inset-y-0 -left-1/3 w-1/3 animate-[scn-progress-indeterminate_1.2s_ease-in-out_infinite]{% endif %}"
       {% if value is not None %}style="width: {{ progress_data.percent }}%"{% endif %}></div>
</div>
{% endlocalize %}

"""Server-side calculations for the Django-Cotton flavour.

Register with TEMPLATES[...]['OPTIONS']['libraries']:
    {'shadcn_htmx': 'shadcn_htmx'}

Tags return data, never marked-safe HTML. Templates retain Django autoescaping.
"""
import math
import re

from django import template

register = template.Library()


def _number(value, default=0):
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    return number if math.isfinite(number) else default


@register.simple_tag
def scn_clamp(value, minimum=0, maximum=100):
    minimum = _number(minimum)
    maximum = max(minimum, _number(maximum, 100))
    return min(maximum, max(minimum, _number(value, minimum)))


@register.simple_tag
def scn_progress(value, minimum=0, maximum=100):
    minimum = _number(minimum)
    maximum = _number(maximum, 100)
    current = scn_clamp(value, minimum, maximum)
    percent = (current - minimum) / (maximum - minimum) * 100 if maximum > minimum else 0
    return {'value': current, 'percent': percent}


@register.simple_tag
def scn_range(low, high, minimum=0, maximum=100):
    low = scn_clamp(minimum if low is None else low, minimum, maximum)
    high = max(low, scn_clamp(maximum if high is None else high, minimum, maximum))
    return {
        'low': low,
        'high': high,
        'low_percent': scn_progress(low, minimum, maximum)['percent'],
        'high_percent': scn_progress(high, minimum, maximum)['percent'],
    }


@register.simple_tag
def scn_stars(maximum=5):
    return range(max(1, int(_number(maximum, 5))), 0, -1)


@register.simple_tag
def scn_split_matches(text, query='', words=False, case_sensitive=False):
    """Preserve source casing and escape query terms before regex matching."""
    text = str(text or '')
    query = str(query or '').strip()
    if not query:
        return [{'text': text, 'match': False}]
    terms = query.split() if words else [query]
    pattern = '|'.join(re.escape(term) for term in terms)
    flags = 0 if case_sensitive else re.IGNORECASE
    segments = []
    end = 0
    for match in re.finditer(pattern, text, flags):
        if match.start() > end:
            segments.append({'text': text[end:match.start()], 'match': False})
        segments.append({'text': match.group(), 'match': True})
        end = match.end()
    if end < len(text):
        segments.append({'text': text[end:], 'match': False})
    return segments
